// Proxy para compatibilidad hacia atrás con código que acceda a EXTRA_NATURALES[n]
export const EXTRA_NATURALES: Record<number, ActivitySpec[]> = new Proxy({} as Record<number, ActivitySpec[]>, {
  get: (_target, prop) => {
    const n = Number(prop);
    return Number.isFinite(n) ? getExtraNaturales(n) : undefined;
  },
});

export function buildNaturalesActivities(world: WorldDef): ActivitySpec[] {
  const n = world.worldNumber ?? 1;
  const count = world.activityCount ?? 8;
  const bank = NATURALES_BANK[n] ?? NATURALES_BANK[1];
  // Tomamos preguntas de opción múltiple del banco
  const qActs = fromBank(bank, Math.max(4, count - 2), `n${n}`, world.skills ?? []);
  // Generamos dinámicamente las actividades interactivas en cada ejecución
  const extraPool = getExtraNaturales(n);
  const extraActs = sample(extraPool, Math.min(2, extraPool.length)).map((a, i) => ({
    ...a,
    id: `${a.id || `n${n}-ex-${i}`}`,
    skills: world.skills && world.skills.length > 0 ? world.skills : (a.skills ?? []),
  }));
  return numbered(shuffle([...qActs, ...extraActs]));
}
